-- Enable required extensions\nCREATE EXTENSION IF NOT EXISTS \"uuid-ossp\";\nCREATE EXTENSION IF NOT EXISTS \"pgvector\";\n\n-- Users table (extends Supabase Auth)\nCREATE TABLE IF NOT EXISTS public.users (\n  id uuid PRIMARY KEY REFERENCES auth.users(id) ON DELETE CASCADE,\n  email text NOT NULL UNIQUE,\n  name text,\n  avatar_url text,\n  google_drive_connected boolean DEFAULT false,\n  google_drive_token_encrypted text,\n  preferences jsonb DEFAULT '{}',\n  created_at timestamp with time zone DEFAULT timezone('utc'::text, now()) NOT NULL,\n  updated_at timestamp with time zone DEFAULT timezone('utc'::text, now()) NOT NULL\n);\n\n-- Subjects table\nCREATE TABLE IF NOT EXISTS public.subjects (\n  id uuid PRIMARY KEY DEFAULT uuid_generate_v4(),\n  user_id uuid NOT NULL REFERENCES public.users(id) ON DELETE CASCADE,\n  name text NOT NULL,\n  description text,\n  color text,\n  created_at timestamp with time zone DEFAULT timezone('utc'::text, now()) NOT NULL,\n  updated_at timestamp with time zone DEFAULT timezone('utc'::text, now()) NOT NULL\n);\n\n-- Conversations table\nCREATE TABLE IF NOT EXISTS public.conversations (\n  id uuid PRIMARY KEY DEFAULT uuid_generate_v4(),\n  user_id uuid NOT NULL REFERENCES public.users(id) ON DELETE CASCADE,\n  subject_id uuid NOT NULL REFERENCES public.subjects(id) ON DELETE CASCADE,\n  title text NOT NULL,\n  messages jsonb DEFAULT '[]',\n  created_at timestamp with time zone DEFAULT timezone('utc'::text, now()) NOT NULL,\n  updated_at timestamp with time zone DEFAULT timezone('utc'::text, now()) NOT NULL\n);\n\n-- Study Sessions table\nCREATE TABLE IF NOT EXISTS public.study_sessions (\n  id uuid PRIMARY KEY DEFAULT uuid_generate_v4(),\n  user_id uuid NOT NULL REFERENCES public.users(id) ON DELETE CASCADE,\n  subject_id uuid NOT NULL REFERENCES public.subjects(id) ON DELETE CASCADE,\n  mode text NOT NULL,\n  started_at timestamp with time zone DEFAULT timezone('utc'::text, now()) NOT NULL,\n  ended_at timestamp with time zone,\n  messages_count integer DEFAULT 0,\n  created_at timestamp with time zone DEFAULT timezone('utc'::text, now()) NOT NULL\n);\n\n-- Uploaded Files table\nCREATE TABLE IF NOT EXISTS public.uploaded_files (\n  id uuid PRIMARY KEY DEFAULT uuid_generate_v4(),\n  user_id uuid NOT NULL REFERENCES public.users(id) ON DELETE CASCADE,\n  conversation_id uuid REFERENCES public.conversations(id) ON DELETE SET NULL,\n  file_name text NOT NULL,\n  file_type text NOT NULL,\n  file_size integer NOT NULL,\n  storage_path text NOT NULL UNIQUE,\n  extracted_text text,\n  created_at timestamp with time zone DEFAULT timezone('utc'::text, now()) NOT NULL\n);\n\n-- Quizzes table\nCREATE TABLE IF NOT EXISTS public.quizzes (\n  id uuid PRIMARY KEY DEFAULT uuid_generate_v4(),\n  user_id uuid NOT NULL REFERENCES public.users(id) ON DELETE CASCADE,\n  subject_id uuid NOT NULL REFERENCES public.subjects(id) ON DELETE CASCADE,\n  title text NOT NULL,\n  questions jsonb NOT NULL,\n  created_at timestamp with time zone DEFAULT timezone('utc'::text, now()) NOT NULL\n);\n\n-- Quiz Attempts table\nCREATE TABLE IF NOT EXISTS public.quiz_attempts (\n  id uuid PRIMARY KEY DEFAULT uuid_generate_v4(),\n  user_id uuid NOT NULL REFERENCES public.users(id) ON DELETE CASCADE,\n  quiz_id uuid NOT NULL REFERENCES public.quizzes(id) ON DELETE CASCADE,\n  score integer NOT NULL,\n  answers jsonb NOT NULL,\n  completed_at timestamp with time zone DEFAULT timezone('utc'::text, now()) NOT NULL\n);\n\n-- Revision Notes table\nCREATE TABLE IF NOT EXISTS public.revision_notes (\n  id uuid PRIMARY KEY DEFAULT uuid_generate_v4(),\n  user_id uuid NOT NULL REFERENCES public.users(id) ON DELETE CASCADE,\n  subject_id uuid NOT NULL REFERENCES public.subjects(id) ON DELETE CASCADE,\n  title text NOT NULL,\n  content text NOT NULL,\n  tags text[],\n  created_at timestamp with time zone DEFAULT timezone('utc'::text, now()) NOT NULL,\n  updated_at timestamp with time zone DEFAULT timezone('utc'::text, now()) NOT NULL\n);\n\n-- Create indexes\nCREATE INDEX idx_subjects_user_id ON public.subjects(user_id);\nCREATE INDEX idx_conversations_user_id ON public.conversations(user_id);\nCREATE INDEX idx_conversations_subject_id ON public.conversations(subject_id);\nCREATE INDEX idx_study_sessions_user_id ON public.study_sessions(user_id);\nCREATE INDEX idx_study_sessions_subject_id ON public.study_sessions(subject_id);\nCREATE INDEX idx_uploaded_files_user_id ON public.uploaded_files(user_id);\nCREATE INDEX idx_uploaded_files_conversation_id ON public.uploaded_files(conversation_id);\nCREATE INDEX idx_quizzes_user_id ON public.quizzes(user_id);\nCREATE INDEX idx_quizzes_subject_id ON public.quizzes(subject_id);\nCREATE INDEX idx_quiz_attempts_user_id ON public.quiz_attempts(user_id);\nCREATE INDEX idx_quiz_attempts_quiz_id ON public.quiz_attempts(quiz_id);\nCREATE INDEX idx_revision_notes_user_id ON public.revision_notes(user_id);\nCREATE INDEX idx_revision_notes_subject_id ON public.revision_notes(subject_id);\n\n-- Enable Row Level Security (RLS)\nALTER TABLE public.users ENABLE ROW LEVEL SECURITY;\nALTER TABLE public.subjects ENABLE ROW LEVEL SECURITY;\nALTER TABLE public.conversations ENABLE ROW LEVEL SECURITY;\nALTER TABLE public.study_sessions ENABLE ROW LEVEL SECURITY;\nALTER TABLE public.uploaded_files ENABLE ROW LEVEL SECURITY;\nALTER TABLE public.quizzes ENABLE ROW LEVEL SECURITY;\nALTER TABLE public.quiz_attempts ENABLE ROW LEVEL SECURITY;\nALTER TABLE public.revision_notes ENABLE ROW LEVEL SECURITY;\n\n-- RLS Policies for Users\nCREATE POLICY \"Users can view their own profile\"\n  ON public.users FOR SELECT\n  USING (auth.uid() = id);\n\nCREATE POLICY \"Users can update their own profile\"\n  ON public.users FOR UPDATE\n  USING (auth.uid() = id);\n\n-- RLS Policies for Subjects\nCREATE POLICY \"Users can view their own subjects\"\n  ON public.subjects FOR SELECT\n  USING (auth.uid() = user_id);\n\nCREATE POLICY \"Users can create subjects\"\n  ON public.subjects FOR INSERT\n  WITH CHECK (auth.uid() = user_id);\n\nCREATE POLICY \"Users can update their own subjects\"\n  ON public.subjects FOR UPDATE\n  USING (auth.uid() = user_id);\n\nCREATE POLICY \"Users can delete their own subjects\"\n  ON public.subjects FOR DELETE\n  USING (auth.uid() = user_id);\n\n-- RLS Policies for Conversations\nCREATE POLICY \"Users can view their own conversations\"\n  ON public.conversations FOR SELECT\n  USING (auth.uid() = user_id);\n\nCREATE POLICY \"Users can create conversations\"\n  ON public.conversations FOR INSERT\n  WITH CHECK (auth.uid() = user_id);\n\nCREATE POLICY \"Users can update their own conversations\"\n  ON public.conversations FOR UPDATE\n  USING (auth.uid() = user_id);\n\nCREATE POLICY \"Users can delete their own conversations\"\n  ON public.conversations FOR DELETE\n  USING (auth.uid() = user_id);\n\n-- RLS Policies for Study Sessions\nCREATE POLICY \"Users can view their own study sessions\"\n  ON public.study_sessions FOR SELECT\n  USING (auth.uid() = user_id);\n\nCREATE POLICY \"Users can create study sessions\"\n  ON public.study_sessions FOR INSERT\n  WITH CHECK (auth.uid() = user_id);\n\n-- RLS Policies for Uploaded Files\nCREATE POLICY \"Users can view their own files\"\n  ON public.uploaded_files FOR SELECT\n  USING (auth.uid() = user_id);\n\nCREATE POLICY \"Users can upload files\"\n  ON public.uploaded_files FOR INSERT\n  WITH CHECK (auth.uid() = user_id);\n\nCREATE POLICY \"Users can delete their own files\"\n  ON public.uploaded_files FOR DELETE\n  USING (auth.uid() = user_id);\n\n-- RLS Policies for Quizzes\nCREATE POLICY \"Users can view their own quizzes\"\n  ON public.quizzes FOR SELECT\n  USING (auth.uid() = user_id);\n\nCREATE POLICY \"Users can create quizzes\"\n  ON public.quizzes FOR INSERT\n  WITH CHECK (auth.uid() = user_id);\n\n-- RLS Policies for Quiz Attempts\nCREATE POLICY \"Users can view their own quiz attempts\"\n  ON public.quiz_attempts FOR SELECT\n  USING (auth.uid() = user_id);\n\nCREATE POLICY \"Users can record quiz attempts\"\n  ON public.quiz_attempts FOR INSERT\n  WITH CHECK (auth.uid() = user_id);\n\n-- RLS Policies for Revision Notes\nCREATE POLICY \"Users can view their own notes\"\n  ON public.revision_notes FOR SELECT\n  USING (auth.uid() = user_id);\n\nCREATE POLICY \"Users can create notes\"\n  ON public.revision_notes FOR INSERT\n  WITH CHECK (auth.uid() = user_id);\n\nCREATE POLICY \"Users can update their own notes\"\n  ON public.revision_notes FOR UPDATE\n  USING (auth.uid() = user_id);\n\nCREATE POLICY \"Users can delete their own notes\"\n  ON public.revision_notes FOR DELETE\n  USING (auth.uid() = user_id);\n"